import{_ as t,a0 as l,w as o,s as r,ao as c,I as p,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 qrcp 在你的手机和 Linux 之间传输文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 qrcp 在你的手机和 Linux 之间传输文件 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 qrcp 在你的手机和 Linux 之间传输文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 qrcp 在你的手机和 Linux 之间传输文件 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211110 Transfer files between your phone and Linux with this open source tool","title":"使用 qrcp 在你的手机和 Linux 之间传输文件","tag":"202111","desc":""},"relativePath":"202111/20211110 Transfer files between your phone and Linux with this open source tool.md","filePath":"[post].md"}'),d={name:"202111/20211110 Transfer files between your phone and Linux with this open source tool.md"};function u(h,s,g,f,k,m){const a=l("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="使用-qrcp-在你的手机和-linux-之间传输文件" tabindex="-1">使用 qrcp 在你的手机和 Linux 之间传输文件 <a class="header-anchor" href="#使用-qrcp-在你的手机和-linux-之间传输文件" aria-label="Permalink to “使用 qrcp 在你的手机和 Linux 之间传输文件”">​</a></h1><blockquote><p>qrcp 项目提供了一种快速地从你的 iPhone 或 Android 设备中复制文件到你的 Linux 电脑的方法，反之也可。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/19/114121wt40ilipix1oo1zh.jpg" alt=""></p><p>你是否在寻找一种快速复制文件的方法，从你的 iPhone 或 Android 移动设备到你的 Linux 电脑，或者从你的 Linux 电脑到你的设备？我最近发现了一个开源的应用，它很容易安装，并且传输文件只需一个二维码。</p><p><code>qrcp</code> 项目提供了一个命令，可以在你的终端生成一个二维码，让你通过网络向你的电脑发送或接收文件。</p><h3 id="在-linux、windows-或-mac-上安装-qrcp" tabindex="-1">在 Linux、Windows 或 Mac 上安装 qrcp <a class="header-anchor" href="#在-linux、windows-或-mac-上安装-qrcp" aria-label="Permalink to “在 Linux、Windows 或 Mac 上安装 qrcp”">​</a></h3><p>开发者 Claudio d&#39;Angelis 以 MIT 许可证发布了 <code>qrcp</code> 应用。我发现它很容易安装，也很容易使用。它适用于 Linux、Windows 和 macOS，可以作为 RPM、DEB 或 tarball 下载。它为几乎所有的平台做了构建，包括树莓派。</p><p>如果你想在 Linux 上安装它，下载 RPM 或 DEB，并使用你的包管理器进行本地安装。例如，在 Fedora、CentOS 或 Mageia，或类似的平台上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ./qrcp*rpm</span></span></code></pre></div><p>如果你只是想试试，你可以下载 tar.gz 压缩包并在本地运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file qrcp*tar.gz</span></span>
<span class="line"><span>$ ./qrcp version</span></span>
<span class="line"><span>qrcp 0.x.y</span></span></code></pre></div><h3 id="设置-qrcp" tabindex="-1">设置 qrcp <a class="header-anchor" href="#设置-qrcp" aria-label="Permalink to “设置 qrcp”">​</a></h3><p>你可以通过使用 <code>--help</code> 选项查看所有可用的 <code>qrcp</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp --help</span></span>
<span class="line"><span>$ ./qrcp --help</span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> qrcp [flags]</span></span>
<span class="line"><span> qrcp [command]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Available Commands:</span></span>
<span class="line"><span> completion  Generate completion script</span></span>
<span class="line"><span> config      Configure qrcp</span></span>
<span class="line"><span> help        Help about any command</span></span>
<span class="line"><span> receive     Receive one or more files</span></span>
<span class="line"><span> send        Send a file(s) or directories from this host</span></span>
<span class="line"><span> version     Print version number and build information.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>默认配置文件位于 <code>~/.config/qrcp/config.json</code> ，你可以使用你喜欢的编辑器编辑，或从命令行调用配置向导来配置应用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp config</span></span></code></pre></div><p>第一步是创建一个配置文件。<code>qrcp config</code> 命令将带你完成这个过程，但会问你几个问题。</p><p>第一个问题是要求你提供一个“完全限定域名”。如果你在一个不使用完全限定域名的本地网络上使用 <code>qrcp</code>（或者你不知道哪种方式），那么就把这个留空。<code>qrcp</code> 命令将使用你的本地 IP 地址代替。</p><p>下一个问题是提示你选择端口。大多数防火墙会阻止非标准的端口，但会将 8080 端口作为互联网流量的情况并不少见。如果你的防火墙屏蔽了 8080 端口，那么你还是要添加一个例外。假设你的系统使用 <code>firewalld</code>，你可以用这个命令允许 8080 端口的流量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port 8080/tcp --permanent</span></span></code></pre></div><p>拒绝在“传输完成后保持网络连接”的选项，让 <code>qrcp</code> 生成一个随机路径。</p><p>假设你在一个可信的网络上，使用 HTTP（而不是 HTTPS）连接，那么你不必配置 TLS。</p><p>配置保存在 <code>~/.config/qrcp/config.json</code> 中，并且之后可以编辑，所以如果你想改变设置，它很容易更新。</p><p>更新后的配置看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;fqdn&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;interface&quot;: &quot;wlp0s20f3&quot;,</span></span>
<span class="line"><span>  &quot;port&quot;: 8080,</span></span>
<span class="line"><span>  &quot;keepAlive&quot;: false,</span></span>
<span class="line"><span>  &quot;path&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;secure&quot;: false,</span></span>
<span class="line"><span>  &quot;tls-key&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;tls-cert&quot;: &quot;&quot;,</span></span>
<span class="line"><span>  &quot;output&quot;: &quot;/home/don&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="用-qrcp-传输文件" tabindex="-1">用 qrcp 传输文件 <a class="header-anchor" href="#用-qrcp-传输文件" aria-label="Permalink to “用 qrcp 传输文件”">​</a></h3><p>现在你已经准备好从你的 Linux 电脑向你的移动设备发送一个文件。在这个例子中，我使用了我的 iPhone，它完全不支持 Linux，这是臭名昭著的。这个过程在安卓设备上是完全一样的。</p><p>我是这样做的。首先，我在我的电脑上创建一个示例文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Hello world&quot;&gt; ~/example.txt</span></span></code></pre></div><p>接下来，我使用 <code>send</code> 子命令将文件从我的 Linux 电脑发送到我的手机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux~$ qrcp send example.txt</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/send-example.png" alt="example of sending a file"></p><p><em>使用 <code>qrcp send example.txt</code> 发送文件的例子（CC BY-SA 4.0）</em></p><p>我打开我的相机应用（在 Android 上，我使用一个保护隐私的专用二维码扫描器），iPhone 扫描二维码并在我的手机上启动 Safari 浏览器。最后，我点击“下载”按钮。</p><p><img src="https://opensource.com/sites/default/files/download-example.png" alt="example download"></p><p><em>下载示例 .txt 文件（CC BY-SA 4.0）</em></p><h3 id="用-qrcp-接收文件" tabindex="-1">用 qrcp 接收文件 <a class="header-anchor" href="#用-qrcp-接收文件" aria-label="Permalink to “用 qrcp 接收文件”">​</a></h3><p>接收文件也一样简单，只是命令略有不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qrcp receive</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/receive-file.png" alt="example of receiving a file"></p><p><em>使用 <code>qrcp receive</code> 命令接收一个文件（CC BY-SA 4.0）</em></p><p>我扫描了二维码，它再次启动了我手机上的 Safari 浏览器，但这次出现了一些不同，因为我正在将文件从我的 iPhone 发送到 Linux 电脑上。</p><p><img src="https://opensource.com/sites/default/files/select-file.jpg" alt="example of selecting a file"></p><p><em>选择一个要传输的文件（CC BY-SA 4.0）</em></p><p>我点击“选择文件”，它让我选择想发送的文件。</p><p><img src="https://opensource.com/sites/default/files/default-location.png" alt="file appears in default location"></p><p><em>文件被下载到默认位置（CC BY-SA 4.0）</em></p><p>发送文件后，是在我的配置中指定的默认位置找到了文件。</p><h3 id="尝试-qrcp" tabindex="-1">尝试 qrcp <a class="header-anchor" href="#尝试-qrcp" aria-label="Permalink to “尝试 qrcp”">​</a></h3><p>项目文档很简短但已足够，除了最初提出这个想法的 Claudio d&#39;Angelis 之外，它还有开发者社区的支持。社区欢迎你加入他们，该应用将改变你对移动设备之间文件传输的看法。试试吧！</p><hr>`,51)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/21/11/transfer-files-phone-linux"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/11/transfer-files-phone-linux",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/don-watkins"},{default:i(()=>[...s[2]||(s[2]=[e("Don Watkins",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=t(d,[["render",u]]);export{x as __pageData,C as default};
